7	function liveNeighborCount(cell: Cell, liveCells: Cell[]): number {
8	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
9	}
10	
11	export function nextGeneration(liveCells: Cell[]): Cell[] {
12	  return liveCells.filter((cell) => liveNeighborCount(cell, liveCells) >= 2);
13	}
